<?php

namespace Database\Seeders;

use App\Models\Control;
use App\Models\ControlEvidence;
use App\Models\User;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\Storage;

/**
 * Attaches a supporting evidence file to every Control that currently
 * has ZERO evidence attached (does NOT touch controls that already
 * have real evidence uploaded — this only fills the gap).
 *
 * Run with:
 *   php artisan db:seed --class=AttachDefaultEvidenceSeeder
 */
class AttachDefaultEvidenceSeeder extends Seeder
{
    // Base64-encoded PDF, embedded directly so this seeder is
    // self-contained and works without any external file.
    private const FILE_BASE64 = <<<'B64'

B64;

    private const ORIGINAL_NAME = 'Rencana_Jadwal_Pengajaran_Ganjil_2627_S1_IF.pdf';

    public function run(): void
    {
        $binary = base64_decode(self::FILE_BASE64);

        $controlsWithoutEvidence = Control::doesntHave('evidences')->get();

        if ($controlsWithoutEvidence->isEmpty()) {
            $this->command->info('No controls without evidence found — nothing to do.');
            return;
        }

        $attached = 0;

        foreach ($controlsWithoutEvidence as $control) {

            $storedName = 'evidence/' . uniqid('ctrl_' . $control->id . '_') . '.pdf';

            Storage::disk('public')->put($storedName, $binary);

            // Resolve a sensible "uploaded_by" name: the Officer/Creator
            // matching this control's UPTI, if one exists.
            $officer = User::query()
                ->where('role', 'creator')
                ->whereHas('upti', function ($q) use ($control) {
                    $q->whereRaw('LOWER(TRIM(name)) = LOWER(TRIM(?))', [$control->upti]);
                })
                ->first();

            ControlEvidence::create([
                'control_id' => $control->id,
                'file_name' => basename($storedName),
                'file_path' => $storedName,
                'original_name' => self::ORIGINAL_NAME,
                'file_type' => 'Supporting Document',
                'mime_type' => 'application/pdf',
                'size' => strlen($binary),
                'uploaded_by' => $officer?->name ?? 'Officer',
            ]);

            $attached++;
        }

        $this->command->info("Attached evidence to {$attached} control(s) that had none.");
    }
}
